create function pg_temp.note_draft(shared boolean) returns uuid language plpgsql set search_path=pg_catalog as $$
declare e uuid:=gen_random_uuid(); o jsonb; v jsonb;
begin
 o:=jsonb_build_object('operation_id',gen_random_uuid(),'kind','set_note','entity_id',e,'base_revision',0,'device_id','e9000000-0000-4000-8000-000000000001','created_at',now(),'payload',jsonb_build_object('workout_instance_id','b9000000-0000-4000-8000-000000000001','text','Synthetic secret marker','shared',shared));
 v:=public.apply_operations('69000000-0000-4000-8000-000000000001',jsonb_build_array(o))->'results'->0;
 if v->>'status' is distinct from 'correction_draft' then raise exception 'Expected correction draft provenance: %',v; end if;
 return (v->>'draft_id')::uuid;
end; $$;
